let root=null, openState=false, view='center', docId='terms', consentFlow=false;
let previousFocus=null, previousInert=false;

function locale(){return document.documentElement.lang==='th'?'th':'en'}
function copy(){return UI[locale()]}
function esc(v=''){return String(v).replace(/[&<>'"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]))}

function installStylesheet(){
  if(document.getElementById(STYLE_ID)) return;
  const link=document.createElement('link');
  link.id=STYLE_ID;link.rel='stylesheet';link.href=STYLE_HREF;link.dataset.aurenLegal='build-31';
  document.head.appendChild(link);
}

function accepted(){
  try{return localStorage.getItem(ACCEPT_VERSION_KEY)===LEGAL_VERSION}catch{return false}
}
function recordAcceptance(){
  try{
    localStorage.setItem(ACCEPT_VERSION_KEY,LEGAL_VERSION);
    localStorage.setItem(ACCEPT_AT_KEY,new Date().toISOString());
  }catch{}
}

function createRoot(){
  if(root) return root;
  root=document.createElement('section');
  root.id='aurenLegalCenter';root.className='auren-legal';root.hidden=true;
  root.setAttribute('role','dialog');root.setAttribute('aria-modal','true');root.setAttribute('aria-labelledby','aurenLegalTitle');
  root.innerHTML=`<header class="auren-legal-top">
    <button class="auren-legal-back" type="button" data-legal-back aria-label="Back">‹</button>
    <div class="auren-legal-brand"><strong>AUREN</strong><small>BENEDICT INTERACTIVE</small></div>
    <button class="auren-legal-close" type="button" data-legal-close aria-label="Close">×</button>
  </header><div class="auren-legal-scroll"><main class="auren-legal-content"></main></div>`;
  document.body.appendChild(root);root.addEventListener('click',onClick);return root;
}
function contentEl(){return createRoot().querySelector('.auren-legal-content')}
function scrollEl(){return createRoot().querySelector('.auren-legal-scroll')}

function languageSwitch(){
  const th=locale()==='th';
  return `<div class="auren-legal-language" role="group" aria-label="Language">
    <button type="button" data-legal-language="en" aria-pressed="${!th}" class="${!th?'is-active':''}">EN</button>
    <button type="button" data-legal-language="th" aria-pressed="${th}" class="${th?'is-active':''}">ไทย</button>
  </div>`;
}
function cards(){
  const order=['terms','privacy','copyright','thirdparty','about'];
  const marks={terms:'§',privacy:'◇',copyright:'©',thirdparty:'↗',about:'A'};
  return order.map(id=>{
    const doc=DOCUMENTS[id];
    return `<button class="auren-legal-card" type="button" data-legal-doc="${id}">
      <span class="auren-legal-mark" aria-hidden="true">${marks[id]}</span>
      <span><strong>${esc(doc.title[locale()])}</strong><small>${esc(doc.subtitle[locale()])}</small></span>
      <span class="auren-legal-arrow" aria-hidden="true">›</span></button>`;
  }).join('');
}
function renderCenter(){
  view='center';consentFlow=false;const c=copy();
  contentEl().innerHTML=`<section class="auren-legal-hero">
    <span class="auren-legal-eyebrow">${esc(c.centerEyebrow)}</span>
    <h1 id="aurenLegalTitle">${esc(c.centerTitle)}</h1><p>${esc(c.centerIntro)}</p>${languageSwitch()}
    <div class="auren-legal-meta"><span>${esc(c.build)} ${BUILD_NUMBER}</span><span>${esc(c.version)} ${LEGAL_VERSION}</span><span>${esc(c.effective)} ${esc(EFFECTIVE)}</span></div>
  </section><section class="auren-legal-cards">${cards()}</section>
  <p class="auren-legal-foot">© 2026 Benedict Interactive · ${esc(c.rights)}</p>`;
  updateChrome();scrollEl().scrollTop=0;
}
function renderConsent(){
  view='consent';consentFlow=true;const c=copy();
  contentEl().innerHTML=`<section class="auren-legal-consent">
    <div class="auren-legal-seal" aria-hidden="true">§</div>
    <span class="auren-legal-eyebrow">${esc(c.consentEyebrow)}</span>
    <h1 id="aurenLegalTitle">${esc(c.consentTitle)}</h1><p>${esc(c.consentBody)}</p>${languageSwitch()}
    <div class="auren-legal-consent-links"><button type="button" data-consent-doc="terms">${esc(c.terms)}</button><button type="button" data-consent-doc="privacy">${esc(c.privacy)}</button></div>
    <button class="auren-legal-agree" type="button" data-legal-agree>${esc(c.agree)}</button>
    <p class="auren-legal-noagree">${esc(c.ifNoAgree)}</p>
    <p class="auren-legal-consent-meta">${esc(c.version)} ${LEGAL_VERSION} · ${esc(c.effective)} ${esc(EFFECTIVE)}</p>
  </section>`;
  updateChrome();scrollEl().scrollTop=0;
  setTimeout(()=>root?.querySelector('[data-legal-agree]')?.focus({preventScroll:true}),20);
}
function renderDocument(id,fromConsent=consentFlow){
  if(!DOCUMENTS[id]) id='terms';view='document';docId=id;consentFlow=Boolean(fromConsent);
  const c=copy(),doc=DOCUMENTS[id];
  const sections=doc.sections[locale()].map(([h,paras])=>`<section class="auren-legal-section"><h2>${esc(h)}</h2>${paras.map(x=>`<p>${esc(x)}</p>`).join('')}</section>`).join('');
  contentEl().innerHTML=`<article class="auren-legal-document"><header>
    <span class="auren-legal-eyebrow">${esc(c.centerEyebrow)}</span><h1 id="aurenLegalTitle">${esc(doc.title[locale()])}</h1>
    <p>${esc(doc.subtitle[locale()])}</p>${languageSwitch()}
    <div class="auren-legal-meta"><span>${esc(c.version)} ${LEGAL_VERSION}</span><span>${esc(c.effective)} ${esc(EFFECTIVE)}</span></div>
  </header><div class="auren-legal-sections">${sections}</div>
  <button class="auren-legal-docback" type="button" data-legal-doc-back>${esc(consentFlow?c.back:c.docBack)}</button></article>`;
  updateChrome();scrollEl().scrollTop=0;
}
function updateChrome(){
  if(!root) return;
  const back=root.querySelector('[data-legal-back]'),closeBtn=root.querySelector('[data-legal-close]');
  if(view==='consent'){back.hidden=true;closeBtn.hidden=true}
  else if(view==='document'&&consentFlow){back.hidden=false;closeBtn.hidden=true}
  else{back.hidden=view==='center';closeBtn.hidden=false}
  back?.setAttribute('aria-label',copy().back);closeBtn?.setAttribute('aria-label',copy().close);
}
function setAppInert(value){
  const app=document.getElementById('app');if(!app)return;
  if(value){previousInert=Boolean(app.inert);app.inert=true}else app.inert=previousInert;
}
function show(){
  createRoot();if(openState)return;previousFocus=document.activeElement;setAppInert(true);
  document.body.classList.add('auren-legal-open');root.hidden=false;openState=true;
  requestAnimationFrame(()=>root.classList.add('is-visible'));
}
function finishClose(){
  root.hidden=true;openState=false;view='center';document.body.classList.remove('auren-legal-open');setAppInert(false);
  if(previousFocus instanceof HTMLElement&&document.contains(previousFocus))previousFocus.focus({preventScroll:true});
  previousFocus=null;
}
function close(){
  if(!openState||consentFlow)return;root.classList.remove('is-visible');
  if(matchMedia('(prefers-reduced-motion: reduce)').matches)finishClose();else setTimeout(finishClose,180);
}
function openCenter(id=''){show();consentFlow=false;if(id&&DOCUMENTS[id])renderDocument(id,false);else renderCenter()}
function openConsent(){show();consentFlow=true;renderConsent()}
function agree(){
  recordAcceptance();consentFlow=false;root.classList.remove('is-visible');
  const done=()=>{root.hidden=true;openState=false;view='center';document.body.classList.remove('auren-legal-open');setAppInert(false);previousFocus=null};
  if(matchMedia('(prefers-reduced-motion: reduce)').matches)done();else setTimeout(done,180);
}
function switchLanguage(target){
  if(!['en','th'].includes(target)||target===locale())return;
  const button=document.getElementById(target==='th'?'thBtn':'enBtn');
  if(button)button.click();else document.documentElement.lang=target;
  if(view==='consent')renderConsent();else if(view==='document')renderDocument(docId,consentFlow);else renderCenter();
  ensureTrigger();
}
function goBack(){
  if(view==='document'){if(consentFlow)renderConsent();else renderCenter()}else if(!consentFlow)close();
}
function onClick(event){
  const doc=event.target.closest('[data-legal-doc]');if(doc){renderDocument(doc.dataset.legalDoc,false);return}
  const consentDoc=event.target.closest('[data-consent-doc]');if(consentDoc){renderDocument(consentDoc.dataset.consentDoc,true);return}
  if(event.target.closest('[data-legal-doc-back],[data-legal-back]')){goBack();return}
  if(event.target.closest('[data-legal-close]')){close();return}
  if(event.target.closest('[data-legal-agree]')){agree();return}
  const language=event.target.closest('[data-legal-language]');if(language)switchLanguage(language.dataset.legalLanguage);
}
function triggerMarkup(button){
  const c=copy();button.innerHTML=`<div class="soft-icon legal-setting-icon" aria-hidden="true">
    <svg viewBox="0 0 24 24"><path d="M7 4.8h10v14.4H7z"/><path d="M9.5 9h5M9.5 12h5M9.5 15h3.2"/></svg></div>
    <div><strong>${esc(c.triggerTitle)}</strong><span>${esc(c.triggerSub)}</span></div><div class="end">›</div>`;
}
function ensureTrigger(){
  let button=document.getElementById('legalCenterBtn');
  if(!button){
    button=document.createElement('button');button.id='legalCenterBtn';button.type='button';
    button.className='setting setting-button legal-center-setting';
    button.addEventListener('click',()=>openCenter());
  }
  if(button.dataset.legalLocale!==locale()){
    triggerMarkup(button);
    button.dataset.legalLocale=locale();
  }
  const polished=document.querySelector('[data-screen="you"] .you-group-about .you-group-surface');
  if(polished){if(button.parentElement!==polished)polished.appendChild(button);return}
  const list=document.querySelector('[data-screen="you"] .settings-list');
  if(list&&!button.isConnected)list.appendChild(button);
}
function waitForSafeGate(){
  if(accepted())return;
  const app=document.getElementById('app'),opening=document.getElementById('opening');let shown=false;
  const observer=new MutationObserver(tryShow);
  function tryShow(){
    if(shown||accepted())return;
    if(!app?.classList.contains('ready'))return;
    if(opening&&!opening.classList.contains('leave'))return;
    shown=true;observer.disconnect();requestAnimationFrame(()=>requestAnimationFrame(openConsent));
  }
  if(app)observer.observe(app,{attributes:true,attributeFilter:['class']});
  if(opening)observer.observe(opening,{attributes:true,attributeFilter:['class']});
  tryShow();
}
function init(){
  installStylesheet();createRoot();ensureTrigger();
  const you=document.querySelector('[data-screen="you"]');
  if(you)new MutationObserver(ensureTrigger).observe(you,{childList:true,subtree:true});
  new MutationObserver(()=>{
    ensureTrigger();if(!openState)return;
    if(view==='consent')renderConsent();else if(view==='document')renderDocument(docId,consentFlow);else renderCenter();
  }).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});
  document.addEventListener('keydown',event=>{
    if(!openState||event.key!=='Escape')return;event.preventDefault();
    if(consentFlow){if(view==='document')renderConsent();return}
    if(view==='document')renderCenter();else close();
  });
  waitForSafeGate();
}
try{
  init();
  window.AurenLegalCenter=Object.freeze({legalVersion:LEGAL_VERSION,accepted,open:openCenter});
}catch(error){console.error('Auren Legal Center unavailable',error)}
